\bottomrule
\end{tabular}
\captionof{table}{Die fünf Verderbnis-Feinde und ihre Gegenmittel}
\end{center}

\section{Wasseraktivität: der wichtigste Wert}

\begin{baustein}
\textbf{Baustein: Merksätze zur Wasseraktivität}
\begin{itemize}
\item Unter ca. 0,70 Wasseraktivität wächst praktisch kein Mikroorganismus
mehr -- das Ziel fast aller Trocknungs- und Salz-Techniken.
\item Wasseraktivität ist nicht gleich Wassergehalt: Honig mit 17 Prozent
Wasser ist stabil, Fleisch mit 70 Prozent nicht.
\item Salz und Zucker binden Wasser: 10 Prozent Salz in einer Lake senken
die Wasseraktivität stärker als 10 Prozent Wasserverdunstung.
\item Faustwert: Wenn Dörgut in der Faust knirscht oder bricht, ist es
trocken genug für die Lagerung.
\end{itemize}
\end{baustein}

\begin{figure}[ht]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-2-1}
\caption{Abb. 2.1 – Wasseraktivität und Haltbarkeit: die Stufenleiter}
\end{figure}

\begin{konzept}{2.2 – Die Stufenleiter der Wasseraktivität}
\textbf{Definition:} Wasseraktivität (aw-Wert) ist das verfügbare freie Wasser
in einem Gut, angegeben von 0 (trocken) bis 1,0 (reines Wasser). Jede
Konservierungstechnik senkt den aw-Wert oder senkt die Temperatur, bei der
der Keim trotzdem nicht wächst.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Ziel-Prüfung: Ordne das Gut einer Stufe der Abb. 2.1 zu. Gehört es
über 0,85, braucht es Kälte, Säure, Salz oder Rauch, nicht nur Trocknung.
\item Technik-Prüfung: Prüfe, ob die Technik die Ziel-Stufe erreicht
(z. B. Dörren von Obst auf unter 0,70, aber Fleisch niemals nur dörren).
\item Kombinations-Prüfung: Prüfe, ob nur ein Hürden-Gegenmittel reicht;
unsicher bedeutet: zwei Hürden setzen (trocken plus gesalzen).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Nutzen: Die Stufenleiter sagt vorher, ob ein Gut ohne Kälte hält.
\item Aufwand: Eine Zuordnung pro Gut, ohne Messgerät über Vergleichsproben.
\item Grenze der Bewertung: Grenzwerte gelten bei Lagerung unter 20 Grad
Celsius und dunkel; im Sommer-Lager gelten sie nicht.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ohne Labor kannst du aw nicht messen. Arbeite
deshalb immer mit der konservativen, nächst-höheren Stufe.
\end{konzept}

