\bottomrule
\end{tabular}
\captionof{table}{Richtwerte der Haltbarkeit; örtlich prüfen}
\end{center}

\begin{stand}
\textbf{Arbeitsstand nach diesem Abschnitt:} Du hast für jedes Gut deiner
Bedarfsliste den Haupt-Verderber benannt, die Ziel-Stufe der
Wasseraktivität zugeordnet und die Konservierungstechnik gewählt. Trage die
Wahl in Formular A.2 ein.
\end{stand}

\begin{konzept}{2.3 – Die Lagerordnung: erst rein, erst raus}
\textbf{Definition:} Lagerordnung ist die räumliche und buchhalterische
Regel, nach der jeder Behälter ein Eintrittsdatum trägt und das
älteste Gut zuerst verbraucht wird (first in, first out).

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Beschriftungs-Prüfung: Trägt jedes Behältnis Inhalt, Datum und
Menge (Vorlage A.4)? Unbeschriftetes gilt als unverwertbar.
\item Zugriffs-Prüfung: Liegt das Älteste vor dem Neueren am Regal?
\item Kontroll-Prüfung: Steht ein fester Kontrolltag im Monat
(Konzept 8.3)?
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Nutzen: Verluste sinken auf die unhintergehbaren 5 bis 15 Prozent
pro Jahr.
\item Aufwand: 30 Minuten pro Monat.
\item Grenze der Bewertung: Die Ordnung hält nur, solange jede eingelegte
Charge dasselbe Schema benutzt.
\end{enumerate}

\textbf{Ehrliche Grenzen:} FIFO funktioniert nicht bei geräumten,
gemischten Kisten; ein Regal pro Gutgruppe ist Pflicht.
\end{konzept}

\section{Kapitel-Checkliste: Ordnung der Haltbarkeit}
\begin{checkliste}
\item Ich habe für jedes meiner Güter den Haupt-Verderber schriftlich
benannt (Tab. 2.1).
\item Ich habe jedem Gut eine Ziel-Stufe der Wasseraktivität zugeordnet
und bei Unsicherheit die höhere Stufe gewählt.
\item Meine Technikwahl steht in Formular A.2 mit Kapitel-Nummer.
\item Jedes Behältnis trägt Inhalt, Datum und Menge (Vorlage A.4).
\item Das älteste Gut liegt vorne und wird zuerst verbraucht.
\item Ein fester monatlicher Kontrolltag steht im Kalender (Konzept 8.3).
\end{checkliste}
