% =====================================================================
\chapter{Salzen und Pökeln: die Währung des Winters}
% =====================================================================

\section*{Zusammenhang in drei Sätzen}

Salz entzieht Wasser aus dem Gut und aus Mikroorganismen; es senkt die
Wasseraktivität bis unter die Wachstumsgrenze. Pökeln ist kontrolliertes
Salzen mit berechneter Menge und Zeit. Die Rechenbasis ist einfach:
Salzmenge, Pökelzeit und Gewicht des Gutes bestimmen Sicherheit und
Haltbarkeit.

\begin{konzept}{5.1 – Trockensalzen nach Gewicht}
\textbf{Definition:} Trockensalzen ist das Einreiben von Fleisch oder Fisch
mit festem Salz ohne Lake. Richtwert: 25 bis 35 g Salz je kg Gut für
kurzzeitliche Pökelung, 40 bis 50 g je kg für Langzeitpökelung über
2 Wochen.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Gewichts-Prüfung: Wiege das Gut roh und notiere das Gewicht in
Vorlage A.5; die Salzdosis richtet sich nach diesem Gewicht.
\item Fleisch-Prüfung: Stammt das Gut von einem gesunden Tier (Band 6)?
Unklarheit heißt: nur auf 75 Grad Celsius durcherhitzen und sofort
verzehren.
\item Gefäß-Prüfung: Pökelt das Gut in einem nicht reaktiven Gefäß
(Emaille, Glas, Steingut, Edelstahl). Verzinktes Blech und Aluminium
sind verboten.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Nutzen: Trockengesalzenes hält bei Kammerkühlung 2 bis 6 Monate.
\item Aufwand: 20 Minuten Arbeit pro 10 kg, laufend nur Kontrolle.
\item Grenze der Bewertung: Zu viel Salz macht das Gut ungenießbar
hart; die Nachsalz-Route führt über Wässern vor dem Verzehr.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ohne Kühlung über 15 Grad Celsius Umgebung
beginnt die Pökelung unsicher zu werden; stelle das Gefäß in die Kammer
(Kapitel 8).
\end{konzept}

\begin{warnbox}
Pökelsalz mit Nitrit (NPÖ, Nitritpökelsalz) ist ein Gift, wenn du es
wie Kochsalz dosierst. Übersteigt die Aufnahme die zulässige Menge, blockiert
es den Sauerstofftransport im Blut; die Schädigung ist schwer und kann
bleibend sein. Miss Nitritpökelsalz nur mit einer Waage auf 1 Gramm genau,
nie mit Löffeln, und verwende es nur mit einer schriftlichen Rechnung nach
Konzept 5.3. Ohne Waage: nur reines Koch- oder Meersalz verwenden und
die Haltbarkeit über länger Salzen und Räuchern erreichen. Ein Fehler bei
der Nitritmenge lässt sich nicht rückgängig machen.
\end{warnbox}

\subsection{Trockensalzen in neun Schritten}

\begin{enumerate}
\item Wiege das ausgenommene, gewaschene und trocken getupfte Gut.
\item Rechne die Salzmenge: 30 g je kg für 14-tägige Pökelung
(Rechenweg Konzept 5.3).
\item Reibe das Salz rundum in das Gut; achte auf Hautfalten und
Knochnä? Es gilt: massiere das Salz in alle Falten und Öffnungen.
\item Lege das Gut in das Pökelgefäß, schwerste Seite unten.
\item Setze ein Auflagebrett mit ca. 2 kg Gewicht (Stein, Ziegel)
darauf; das Salzwasser muss das Gut in den nächsten Tagen überdecken.
\item Stelle das verschlossene Gefäß in die Kammer bei 4 bis 10 Grad
Celsius.
\item Wende das Gut alle 3 Tage: oberste Seite nach unten.
\item Prüfe nach zwei Dritteln der Zeit die Lake: Sie muss klar und
salzig riechen; trübe oder süßlich riechende Lake heißt Charge
verwerfen.
\item Nach Ablauf der Pökelzeit: Gut abschwemmen und 24 Stunden
wässern (frisches Wasser alle 6 Stunden), dann räuchern (Kapitel 4)
oder trocken lagern.
\end{enumerate}

\begin{figure}[ht]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-5-1}
\caption{Abb. 5.1 – Pökelgefäß mit Auflagegewicht: Schnittbild}
\end{figure}

\begin{konzept}{5.2 – Nasspökeln mit Lake}
\textbf{Definition:} Nasspökeln legt das Gut vollständig in eine
Salzlösung (Lake). Standard-Lake: 200 g Salz auf 1 Liter Wasser für
die erste Pökelung; eine harte Lake mit 300 g je Liter verlängert
die Haltbarkeit, macht das Gut aber salziger.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Löse-Prüfung: Ist das Salz vollständig gelöst? Ungelöste
Kristalle salzen lokal über; rühre, bis der Boden klar ist.
\item Bedeckungs-Prüfung: Schwimmt das Gut vollständig in der Lake?
Freie Teile faulen zuerst; benutze das Auflagebrett.
\item Austausch-Prüfung: Wird die Lake bei trübem Geruch komplett
erneuert und das Gut gut abgespült?
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Nutzen: Die Lake verteilt das Salz gleichmäßiger als Trockensalzen
und eignet sich für viele kleine Stücke.
\item Aufwand: 10 Minuten Arbeit, aber 40 Prozent mehr Salzverbrauch.
\item Grenze der Bewertung: Lake fault schneller als das Gut selbst;
bei über 12 Grad Celsius Lagerung täglich prüfen.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Eine gebrauchte Lake gehört zu keinem
zweiten Gut; aufkochen (5 Minuten sprudelnd) macht sie für die
nächste Charge gleicher Güte wieder brauchbar.
\end{konzept}

\subsection{Pökelzeit-Tabelle}

\begin{center}
\begin{tabular}{p{3.6cm} p{2.8cm} p{3.2cm} p{4.6cm}}
\toprule
Gut & Gewicht/Stärke & Pökelzeit & Besonderheit \\
\midrule
Speck, Rücken & bis 2 kg & 10--14 Tage & wässern 24 h \\
Schinken, Keule & 4--8 kg & 3--4 Wochen & Kernsonde: Sud austreten
lassen \\
Fisch (Forelle) & 300 g & 2 Tage & danach kalt räuchern \\
Fisch (groß) & über 1 kg & 4--5 Tage & festes Salz voller Kontakt \\
Geflügel & 1--2 kg & 5--7 Tage & innen Lake nachfüllen \\
\bottomrule
\end{tabular}
\captionof{table}{Pökelzeiten nach Gewicht; örtlich prüfen}
\end{center}

\begin{konzept}{5.3 – Lake berechnen: der Rechenweg}
\textbf{Definition:} Lake-Rechnung bedeutet: Salzmenge = Wassermenge mal
Zielkonzentration. Für eine Standard-Lake mit 20 Prozent Ziel: 1 Liter
Wasser mal 200 g je Liter = 200 g Salz.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Mengen-Prüfung: Wie viel Liter Wasser brauchst du, um das Gut
zu überdecken? Miss in Litern, rechne in Gramm.
\item Konzentration-Prüfung: Prüfe die Zielkonzentration in der
Tabelle; bei unsicherem Lager die höhere Stufe wählen.
\item Eihaltungs-Prüfung: Notiere Ansatz, Datum und Ziel-Abholtermin
in Vorlage A.5.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Nutzen: Die Rechnung verhindert salzlose Chargen -- die
häufigste Ursache für Verderb trotz Pökelung.
\item Aufwand: 5 Minuten mit Waage und Messbecher.
\item Grenze der Bewertung: Ohne exakte Waage bleibt die Konzentration
eine Schätzung; dann nur Zeit- und Geruchskontrolle als Reserve.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Die Rechnung gilt nur bei vollständigem
Salz-Kontakt; Hohlräume (Bauchhöhle) brauchen nachgefüllte Lake.
\end{konzept}

\subsection{Salz-Sparsatz-Übersicht (Gültige Werte im Fall)}

\begin{center}
\begin{tabular}{p{4.4cm} p{5.2cm} p{4.6cm}}
\toprule
Ziel & Salzmenge & Folge \\
\midrule
Kurze Haltbarkeit (Wochen) & 20 g je kg Trockensalz &
mild, kurze Pökelzeit \\
Standard (Monate) & 30 g je kg Trockensalz & hart bei langer Lagerung \\
Standard-Lake & 200 g je Liter & gleichmäßig, mild \\
Harte Lake & 300 g je Liter & lange Haltbarkeit, salzig; wässern \\
\bottomrule
\end{tabular}
\captionof{table}{Salzmengen nach Ziel; Faustwerte}
\end{center}

\begin{baustein}
\textbf{Baustein: Salz-Merksätze}
\begin{itemize}
\item Salz braucht Zeit: Verdop? Es gilt: doppelte Pökelzeit ist
sicherer als doppelte Salzdosis.
\item Das Gut muss immer unter Lake oder unter Salz bleiben.
\item Trübe Lake ohne Salzgeruch ist verdorben -- wegwerfen ohne
Rettungsversuch.
\item Nach dem Wässern wieder abtrocknen lassen, sonst Schimmelrisiko.
\end{itemize}
\end{baustein}

\subsection{Stadt-Land-Entscheidungstabelle Salzen}

\begin{center}
\begin{tabular}{p{4cm} p{5.2cm} p{5.2cm}}
\toprule
Fall & Stadt & Land \\
\midrule
Kühler Lagerraum vorhanden? & Kellerflur unter 12 Grad Celsius:
ja & Keller, Nordwand: ja; sonnige Wirtschaftsräume: nein \\
Salzbesorgung & Vorratskauf in Mengenpackungen über 10 kg prüfen &
Sole für Vieh oder Streusalz (nur gereinigt!) prüfen; örtlich
prüfen \\
Räucheranschluss & Nachbarschafts-Ofen für Gemeinschaftsräuchern &
eigener Erdofen nach Abb. 4.1 \\
\bottomrule
\end{tabular}
\captionof{table}{Salzen: Entscheidungen für Stadt und Land}
\end{center}

\section{Kapitel-Checkliste: Salzen und Pökeln}
\begin{checkliste}
\item Jede Charge wurde gewogen und die Salzdosis nach Konzept 5.3
aufgeschrieben.
\item Das Pökelgefäß ist nicht reaktiv: Emaille, Glas, Steingut oder
Edelstahl.
\item Das Gut lag vollständig unter Salz oder Lake, mit Auflagegewicht.
\item Die Pökelzeit nach Tab. 5.1 ist eingehalten und notiert.
\item Lake wurde bei Trübung komplett erneuert oder die Charge
verworfen.
\item Nach der Pökelung wurde 24 Stunden gewässert und abgetrocknet.
\item Nitritpökelsalz wurde -- wenn überhaupt -- grammgenau mit Waage
dosiert (Warnung in diesem Kapitel).
\end{checkliste}
